        if isinstance(e, Vn):
            return list(_cov_query(self._h, _f.fit_vn_std_dev, e._p, 4))
        if isinstance(e, Wrap):
            return list(_cov_query(self._h, _f.fit_wrap_std_dev, e._p, 1))
        raise TypeError("no std_dev for %r" % (e,))
